import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the feature card image
  const material = new MeshBasicNodeMaterial();
  material.colorNode = uv().mul(vec3(1.0));

  let textureNode = null;
  const mesh = new THREE.Mesh(geometry, material);

  // Load texture asynchronously and update material
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      textureNode = texture(tex);
      material.colorNode = textureNode;
      material.needsUpdate = true;
    });
  }

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    mesh.position.set(config.scenePosition.x, config.scenePosition.y, config.scenePosition.z);
  }
  if (config.sceneRotation) {
    mesh.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }
  if (config.sceneScale) {
    mesh.scale.set(config.sceneScale.x, config.sceneScale.y, config.sceneScale.z);
  }

  // Setup userData for cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureNode && textureNode.value) {
      textureNode.value.dispose();
    }
  };

  return mesh;
}
